import{_ as e,o as i,c as r,a3 as o}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"数字电路","description":"","frontmatter":{"translationSource":{"title":"数字电路","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Yh0HLXCoQQ27V3mZ1Nxpyg","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/digital-circuits"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/digital-circuits"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/digital-circuits"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/digital-circuits"}]]},"headers":[],"relativePath":"zh/digital-circuits.md","filePath":"zh/page-Yh0HLXCoQQ27V3mZ1Nxpyg.md"}'),t={name:"zh/digital-circuits.md"};function c(l,a,p,s,d,n){return i(),r("div",null,[...a[0]||(a[0]=[o('<div class="logistics-content"><h1 id="数字电路" tabindex="-1">数字电路 <a class="header-anchor" href="#数字电路" aria-label="Permalink to &quot;数字电路&quot;">​</a></h1><blockquote><p>源页面 ID：<code>Yh0HLXCoQQ27V3mZ1Nxpyg</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Yh0HLXCoQQ27V3mZ1Nxpyg" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>以下是群主老大负责部分内容</p><p><span id="source-block-YZ6VeUpQiBgrSopI5kB9Ua"></span></p><h2 id="数字电路控制系统" tabindex="-1">数字电路控制系统 <a class="header-anchor" href="#数字电路控制系统" aria-label="Permalink to &quot;数字电路控制系统&quot;">​</a></h2><p><span id="source-block-EnP43uHPu7gRUdMRKQOpSk"></span></p><h3 id="周期点信号的生成" tabindex="-1">周期点信号的生成 <a class="header-anchor" href="#周期点信号的生成" aria-label="Permalink to &quot;周期点信号的生成&quot;">​</a></h3><p>如图所示，利用<a href="/endfield-skydoc/zh/basic-factory-principles#source-block-7R9931VccE38fQGWecdJ9R">基础基建原理</a>，可以做到每100秒输出一个蓝铁矿。</p><p>定义一种下游流通的物流，称为点信号物流，在这种物流稳定后，下游的每个物品的输出间隔都为尽可能大的固定时间间隔T的倍数，其中T相当大。显然，上面给出的蓝铁矿物流线是一个点信号物流，其T取100s，称T为该点信号物流的时钟周期，1/T为该点信号的时钟频率f，即10mHz。</p><p><span id="source-block-z2Za4dfyLVXsRqMMoPrgK3"></span></p><h3 id="时钟采样" tabindex="-1">时钟采样 <a class="header-anchor" href="#时钟采样" aria-label="Permalink to &quot;时钟采样&quot;">​</a></h3><p>反馈的要求是，将反馈源的流量状态转化为表示状态的数字信号0和1，其中0代表反馈源无效，1代表反馈源有效，容易想到，如果能够将反馈源的输出进行一定的整流，将其在一定时钟周期内的输出集中在周期内的同一段，例如：</p><p>1010101010——&gt;1110011000</p><p>利用<a href="/endfield-skydoc/zh/logistics-principles-and-frontier-research#source-block-f5f4WE5OyQHLDbhWbKgmAv">物流原理与一些名词</a>的结果，可以构造如图的装置，来达到上面的需求。</p><p>就可以通过对于时钟周期内某一个点进行采样来比较反馈源在一段时间内的输出总量与某个设定值的大小，如果更大，则采样为1，反之则采样为0。这个设定值的选取由采样点在单个时钟周期中的位置决定。</p><p>这个采样装置很好搭建，如图所示：</p><p><span id="source-block-JuE8e1LcfMB49QplhfUWqT"></span></p><h3 id="信号放大" tabindex="-1">信号放大 <a class="header-anchor" href="#信号放大" aria-label="Permalink to &quot;信号放大&quot;">​</a></h3><p>我们有时需要复用点信号，利用两次取补可以复制流量，这种功能可以集成为如下的信号放大器，其中每个出口都能输出一个复制信号：</p><p><span id="source-block-HHuZkGBvhHGd7puOwrgATO"></span></p><h3 id="信号运算" tabindex="-1">信号运算 <a class="header-anchor" href="#信号运算" aria-label="Permalink to &quot;信号运算&quot;">​</a></h3><p>利用协议存储箱的优先级，可以对点信号进行逻辑运算，其规律与<a href="/endfield-skydoc/zh/basic-factory-principles#source-block-EHhBNcPi9z2GuxnXC3X587">基础基建原理</a>中的简单逻辑运算完全相同。这种逻辑运算中的1为点信号物流在单个时钟周期中有一个输出，0为点信号物流在单个时钟周期中没有输出。</p><p>需要额外注意的是，如果信号运算的最后一次非运算后没有与运算，就意味着产生的运算将会是一个几乎是满的补带，不符合点信号物流要求，需要额外与高电平信号做一次与。</p><p><span id="source-block-x3ZJ3xNYB6VgMGagCAaz3A"></span></p><h3 id="信号还原" tabindex="-1">信号还原 <a class="header-anchor" href="#信号还原" aria-label="Permalink to &quot;信号还原&quot;">​</a></h3><p>经过运算后，需要将运算结果转化为输出，这里运算结果的含义为，如果运算产生了输出信号，则下游在本周期则不会持续输出反应原料。可以构造如图所示的装置来完成这一功能：</p><p>其中运算产生的输出信号蓝铁矿进入协议箱后，协议箱被阻塞，电池无法经过协议箱输出，其补带在延时一个周期时间后抵达协议箱出口，如果此时运算产生的输出信号停止，蓝铁输出，协议箱阻塞解除，在下个周期电池将持续输出。反之则蓝铁同时输入输出，蓝铁在协议箱中依然保有一个，协议箱阻塞保持，电池无法被输出。</p><p><span id="source-block-fc6GxHsFbpcKbKS9i9cPX6"></span></p><h3 id="利用延时器来改善性能" tabindex="-1">利用延时器来改善性能 <a class="header-anchor" href="#利用延时器来改善性能" aria-label="Permalink to &quot;利用延时器来改善性能&quot;">​</a></h3><p><a href="/endfield-skydoc/zh/logistics-principles-and-frontier-research#source-block-f5f4WE5OyQHLDbhWbKgmAv">物流原理与一些名词</a>中提到的滤波器消耗反应元件数和空间数极大，对于实际运用并不友好，而信号还原也要求延时一个周期时间，需要拉很长的传送带。可以通过一个内部流通的限流器来达到延时的作用，比如这就是一个100s的延时器：</p><p>利用这个延时器，可以简化信号还原的延时步骤，也就是说，能够依靠一个周期为2T的高电平点信号和一个延时为T的信号还原器来构造一个周期为2T的标准方波信号。依靠这个方波信号，可以将采样器的滤波装置简化如下，大大减少了占地和元件数：</p></div>',1)])])}const f=e(t,[["render",c]]);export{u as __pageData,f as default};
